css:
@page {
	size: A4 landscape;
	margin: 8mm 6mm;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
	font-family: Arial, Helvetica, sans-serif !important;
	font-size: 6pt !important;
	color: #000 !important;
	background: #fff !important;
}

.cac-excel {
	width: 100%;
	color: #000;
}

.cac-doc-ref {
	font-size: 7pt;
	margin-bottom: 2px;
}

.cac-grid,
.cac-assessors,
.cac-legend {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}

.cac-grid th,
.cac-grid td,
.cac-assessors th,
.cac-assessors td,
.cac-legend td {
	border: 1px solid #000;
	padding: 1px 2px;
	vertical-align: middle;
	line-height: 1.05;
	word-wrap: break-word;
}

.head-grey th {
	background: #d9d9d9 !important;
	font-weight: 700;
	text-align: center;
	font-size: 5.5pt;
}

.label-col {
	width: 52px;
	text-align: left;
	font-size: 5.5pt;
}

.name-col {
	width: 90px;
}

.row-no {
	width: 18px;
	text-align: center;
	font-size: 6pt;
}

.learner-name {
	width: 90px;
	font-size: 6pt;
	text-align: left;
}

.learner-row td {
	height: 14px;
}

.outcome-code,
.method-code {
	font-size: 5pt;
	text-align: center;
	min-width: 14px;
}

.module-code {
	font-size: 5.5pt;
	font-weight: 700;
}

.module-title {
	font-size: 5pt;
	font-weight: 400;
}

.result-cell {
	text-align: center;
	font-size: 5.5pt;
	height: 14px;
}

.remarks-col {
	width: 48px;
	font-size: 5.5pt;
}

.remarks-cell {
	font-size: 5.5pt;
}

.cac-ebs-line {
	margin: 4px 0;
	font-size: 6pt;
}

.cac-legend td {
	border: none;
	font-size: 5.5pt;
	padding: 3px 2px;
	vertical-align: top;
}

.legend-left {
	width: 65%;
}

.legend-right {
	width: 35%;
	text-align: right;
}

.cac-assessors {
	margin-top: 6px;
}

.cac-assessors th,
.cac-assessors td {
	font-size: 6pt;
}

.a-sr { width: 16px; text-align: center; }
.a-name { width: 80px; }
.a-module { width: 70px; }
.a-desc { width: 90px; }
.a-sign { width: 70px; text-align: center; }
.a-date { width: 55px; }
.a-day { width: 55px; }
.a-time { width: 45px; }

.sig-img {
	max-height: 22px;
	max-width: 65px;
	object-fit: contain;
}

.cac-footer {
	margin-top: 8px;
	font-size: 6pt;
	display: flex;
	justify-content: space-between;
}

* {
	-webkit-print-color-adjust: exact !important;
	print-color-adjust: exact !important;
}

.cac-grid tr,
.cac-assessors tr {
	page-break-inside: avoid;
}

html:
{% set template = frappe.get_doc('Assessment Checklist Template', doc.template) %}

{% set ns = namespace(columns=[], module_groups=[], results_map={}, current_code='') %}
{% for row in template.criteria %}
	{% set _ = ns.columns.append({
		'learning_outcome': row.learning_outcome or '',
		'source_of_evidence': row.source_of_evidence or '',
		'unit_code': row.unit_code or '',
		'module_name': row.module_name or ''
	}) %}
{% endfor %}

{% for col in ns.columns %}
	{% if ns.module_groups and ns.module_groups[-1].unit_code == col.unit_code %}
		{% set _ = ns.module_groups[-1].update({'span': ns.module_groups[-1].span + 1}) %}
	{% else %}
		{% set _ = ns.module_groups.append({'unit_code': col.unit_code, 'module_title': col.module_name, 'span': 1}) %}
	{% endif %}
{% endfor %}

{% for row in doc.assessment_results %}
	{% set rkey = row.candidate ~ '|' ~ (row.learning_outcome or '') ~ '|' ~ (row.source_of_evidence or '') %}
	{% set _ = ns.results_map.update({rkey: row.result or ''}) %}
{% endfor %}

<div class="cac-excel">
	<div class="cac-doc-ref">{{ doc.document_no or template.document_no or '' }}</div>

	<table class="cac-grid">
		<tr class="head-grey">
			<th class="label-col">Outcome &amp; Sub-Outcomes</th>
			<th class="name-col"></th>
			{% for col in ns.columns %}
			<th class="outcome-code">{{ col.learning_outcome }}</th>
			{% endfor %}
			<th class="remarks-col" rowspan="4">Remarks</th>
		</tr>
		<tr class="head-grey">
			<th class="label-col">Assessment Method</th>
			<th class="name-col"></th>
			{% for col in ns.columns %}
			<th class="method-code">{{ col.source_of_evidence }}</th>
			{% endfor %}
		</tr>
		<tr class="head-grey">
			<th class="label-col">Learner Name</th>
			<th class="name-col"></th>
			{% for mg in ns.module_groups %}
			<th class="module-code" colspan="{{ mg.span }}">{{ mg.unit_code }}</th>
			{% endfor %}
		</tr>
		<tr class="head-grey">
			<th class="label-col"></th>
			<th class="name-col"></th>
			{% for mg in ns.module_groups %}
			<th class="module-title" colspan="{{ mg.span }}">{{ mg.module_title }}</th>
			{% endfor %}
		</tr>

		{% for i in range(1, 17) %}
		{% set candidate = doc.candidates[i - 1] if doc.candidates|length >= i else None %}
		<tr class="learner-row">
			<td class="row-no">{{ i }}</td>
			<td class="learner-name">{{ candidate.candidate_name if candidate else '' }}</td>
			{% for col in ns.columns %}
				{% set rkey = (candidate.candidate if candidate else '') ~ '|' ~ col.learning_outcome ~ '|' ~ col.source_of_evidence %}
				<td class="result-cell">{{ ns.results_map[rkey] if rkey in ns.results_map else '' }}</td>
			{% endfor %}
			<td class="remarks-cell">{{ candidate.remarks if candidate else '' }}</td>
		</tr>
		{% endfor %}
	</table>

	{% if 'EBS' in (template.checklist_type or '')|upper %}
	<p class="cac-ebs-line"><strong>Demo EBS used by</strong> ________________________________</p>
	{% endif %}

	<table class="cac-legend">
		<tr>
			<td class="legend-left">
				Assessment Methods: (DO)-Direct Observation, (GD)-Group Discussion, (WA)-Written Assessment, (OQ)-Oral Questioning
			</td>
			<td class="legend-right">
				Final Assessment Result: C-Competent, NYC-Not Yet Competent
			</td>
		</tr>
	</table>

	{% if doc.assessor_signatures %}
	<table class="cac-assessors">
		<tr class="head-grey">
			<th class="a-sr"></th>
			<th class="a-name">Assessor Name</th>
			<th class="a-module">Module</th>
			<th class="a-desc">Description</th>
			<th class="a-sign">Signature</th>
			<th class="a-date">Date</th>
			<th class="a-day">Day</th>
			<th class="a-time">Time<br>AM / PM</th>
		</tr>
		{% for row in doc.assessor_signatures %}
		<tr>
			<td class="a-sr">{{ loop.index }}</td>
			<td class="a-name">{{ row.assessor_name or '' }}</td>
			<td class="a-module">{{ row.unit_code or '' }}</td>
			<td class="a-desc">{{ row.module_name or '' }}</td>
			<td class="a-sign">{% if row.signature %}<img src="{{ row.signature }}" class="sig-img" />{% endif %}</td>
			<td class="a-date">{{ frappe.utils.formatdate(row.assessment_date, 'dd-MM-yyyy') if row.assessment_date else '' }}</td>
			<td class="a-day"></td>
			<td class="a-time">{{ row.time or '' }}</td>
		</tr>
		{% endfor %}
	</table>
	{% endif %}

	<div class="cac-footer">
		<span>{{ doc.document_no or template.document_no or '' }}</span>
		{% if doc.course_date %}<span>Date: {{ frappe.utils.formatdate(doc.course_date, 'dd-MM-yyyy') }}</span>{% endif %}
	</div>
</div>
